    uniform float uTime;
    varying vec3 vN; varying vec3 vV;
    float arm(vec3 d, vec3 a){ float c = max(dot(d, normalize(a)), 0.0); return 1.3*pow(c, 12.0); }
    vec3 shape(vec3 d){
      d = normalize(d);
      float r = 0.36 + arm(d, vec3(1.,1.,1.)) + arm(d, vec3(1.,-1.,-1.)) + arm(d, vec3(-1.,1.,-1.)) + arm(d, vec3(-1.,-1.,1.));
      r += sin(d.x*6.0 + uTime)*0.012 + sin(d.y*5.0 - uTime*0.8)*0.012;
      return d * r;
    }
    void main(){
      vec3 d = normalize(position);
      vec3 up = abs(d.y) < 0.99 ? vec3(0.,1.,0.) : vec3(1.,0.,0.);
      vec3 t = normalize(cross(d, up)); vec3 b = normalize(cross(d, t));
      vec3 p = shape(d), p1 = shape(d + t*0.006), p2 = shape(d + b*0.006);
      vec3 n = normalize(cross(p1 - p, p2 - p)); if (dot(n, p) < 0.0) n = -n;
      vec4 mv = modelViewMatrix * vec4(p, 1.0);
      vN = normalize(normalMatrix * n); vV = normalize(-mv.xyz);
      gl_Position = projectionMatrix * mv;
    }

